<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;

class DatabaseSeeder extends Seeder
{
    /**
     * Seed the application's database with the DAG reference data and a
     * demo workflow. Model events stay enabled: UUID primary keys and
     * human-readable references (DAG-CTR-2026-0001, …) are generated by
     * `creating` hooks on the domain models.
     */
    public function run(): void
    {
        $this->call([
            MembresEquipeSeeder::class,
            CatalogueSeeder::class,
            LigneTarifaireSeeder::class,
            FormationSeeder::class,
            EntreprisesPartenairesSeeder::class,
            ClientsEtApprenantsSeeder::class,
            DemoWorkflowSeeder::class,
        ]);
    }
}
